css:
  :root { --loss: #cc3311; --ink: #0f2340; --tongue: #f0789a; --glove: #1c1f26; }
  svg { width: 220px; height: 238px; overflow: visible; filter: drop-shadow(0 14px 24px rgba(0,0,0,.35)); }

  /* Shared mask parts, as on the site. */
  .head { fill: var(--loss); stroke: var(--ink); stroke-width: 4; }
  .seam { stroke: var(--ink); stroke-width: 3; opacity: .45; fill: none; }
  .patch { fill: var(--ink); }
  .x { stroke: #fff; stroke-width: 5; stroke-linecap: round; fill: none; }
  [class*="spin"], .tongue, .wobble, .half, .droop, .star { transform-box: view-box; }

  /* Every mask drops in the way the site's does. */
  .drop { animation: drop 1.8s cubic-bezier(.2,1.5,.4,1); transform-box: view-box; transform-origin: 50% 50%; }
  @keyframes drop {
    0% { opacity: 0; transform: translateY(-60px) scale(.4) rotate(-30deg); }
    25% { opacity: 1; transform: translateY(0) scale(1.15) rotate(10deg); }
    40% { transform: scale(1) rotate(-6deg); }
    55% { transform: rotate(3deg); }
    100% { opacity: 1; transform: rotate(0); }
  }

  /* 2. Heartbreak: the halves drift apart and the head droops. */
  .half { animation: split-l 2.4s ease-in-out 1.2s infinite alternate; transform-origin: 100px 192px; }
  .half.r { animation-name: split-r; }
  @keyframes split-l { to { transform: translate(-5px, 2px) rotate(-9deg); } }
  @keyframes split-r { to { transform: translate(5px, 2px) rotate(9deg); } }
  .droop { animation: droop 3s ease-in-out 1s infinite alternate; transform-origin: 100px 104px; }
  @keyframes droop { from { transform: rotate(-12deg); } to { transform: rotate(-20deg) translateY(3px); } }
  .tear { fill: #8fd3ff; stroke: var(--ink); stroke-width: 1.5; animation: tear 2.2s ease-in 1.6s infinite; opacity: 0; }
  @keyframes tear { 0% { opacity: 0; transform: translateY(0); } 15% { opacity: 1; } 100% { opacity: 0; transform: translateY(26px); } }

  /* 3. Tongue: it wags, the head lolls. */
  .tongue { fill: var(--tongue); stroke: var(--ink); stroke-width: 3; transform-origin: 60px 100px; animation: wag .5s ease-in-out infinite alternate; }
  .tongue-line { stroke: #c94d70; stroke-width: 2; fill: none; stroke-linecap: round; }
  @keyframes wag { from { transform: rotate(-14deg); } to { transform: rotate(14deg) scaleY(1.08); } }
  .wobble { transform-origin: 60px 120px; animation: loll 1.6s ease-in-out 1.8s infinite alternate; }
  @keyframes loll { from { transform: rotate(-5deg); } to { transform: rotate(5deg); } }
  .mouth { fill: var(--ink); }
  .eye { fill: #fff; }

  /* 4. Knocked silly: the head boings, the eyes spin, stars orbit. */
  .boing { transform-box: view-box; transform-origin: 60px 124px; animation: boing 1.1s cubic-bezier(.3,1.6,.5,1) 1.8s infinite; }
  @keyframes boing {
    0%, 100% { transform: rotate(0) scale(1, 1); }
    20% { transform: rotate(-16deg) scale(1.06, .92); }
    45% { transform: rotate(14deg) scale(.95, 1.06); }
    70% { transform: rotate(-6deg) scale(1.02, .98); }
  }
  .spin-l { transform-origin: 37px 61px; animation: spin 1s linear infinite; }
  .spin-r { transform-origin: 83px 61px; animation: spin 1s linear infinite reverse; }
  @keyframes spin { to { transform: rotate(360deg); } }
  .spiral { fill: none; stroke: #fff; stroke-width: 3.5; stroke-linecap: round; }
  .orbit { transform-box: view-box; transform-origin: 60px 4px; animation: orbit 1.6s linear infinite; }
  @keyframes orbit { to { transform: rotate(360deg); } }
  .star { fill: #ffd23f; stroke: var(--ink); stroke-width: 1.5; }
  .tongue.fast { animation-duration: .22s; }

  /* 5. Side tongue: a long tongue swings from the corner of the mouth and drools. */
  .swing { transform-box: view-box; transform-origin: 76px 101px; animation: swing 1.3s ease-in-out infinite alternate; }
  @keyframes swing { from { transform: rotate(-10deg); } to { transform: rotate(16deg); } }
  .drool { fill: #bfe6ff; stroke: var(--ink); stroke-width: 1.2; transform-box: view-box; animation: drool 1.8s ease-in 1.8s infinite; opacity: 0; }
  @keyframes drool { 0% { opacity: 0; transform: translateY(0) scaleY(.6); } 20% { opacity: 1; transform: translateY(2px) scaleY(1.3); } 100% { opacity: 0; transform: translateY(30px); } }
  .lid { fill: var(--loss); }

  /* 6. Raspberry: the head shakes, the tongue buzzes, spit flies. */
  .shake { transform-box: view-box; transform-origin: 60px 120px; animation: shake .16s linear 1.8s infinite alternate; }
  @keyframes shake { from { transform: rotate(-3deg) translateX(-1px); } to { transform: rotate(3deg) translateX(1px); } }
  .buzz { transform-box: view-box; transform-origin: 60px 102px; animation: buzz .07s linear infinite alternate; }
  @keyframes buzz { from { transform: scale(1, .9); } to { transform: scale(1.06, 1.08) translateY(1px); } }
  .spit { fill: #bfe6ff; stroke: var(--ink); stroke-width: 1; transform-box: view-box; animation: spit .7s ease-out infinite; opacity: 0; }
  .spit.b { animation-delay: .23s; } .spit.c { animation-delay: .46s; }
  @keyframes spit { 0% { opacity: 1; transform: translate(0, 0) scale(.6); } 100% { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(1.1); } }
  .pfft { font: 900 15px/1 system-ui, sans-serif; fill: #fff; stroke: var(--ink); stroke-width: 3; paint-order: stroke; letter-spacing: 1px; transform-box: view-box; transform-origin: 104px 116px; animation: pfft .7s ease-out 1.8s infinite; }
  @keyframes pfft { 0% { transform: scale(.6) rotate(-8deg); opacity: 0; } 30% { opacity: 1; transform: scale(1.1) rotate(6deg); } 100% { transform: scale(1) rotate(10deg); opacity: 0; } }
  .squint { fill: none; stroke: #fff; stroke-width: 5; stroke-linecap: round; stroke-linejoin: round; }

  /* 7. Coin spin: the head flips round twice, then wobbles to a stop. */
  .coin { transform-box: view-box; transform-origin: 60px 66px; animation: coin 3s ease-in-out 1.8s infinite; }
  @keyframes coin {
    0% { transform: scaleX(1); }
    12% { transform: scaleX(-1); }
    24% { transform: scaleX(1); }
    36% { transform: scaleX(-1); }
    48% { transform: scaleX(1) rotate(0); }
    58% { transform: rotate(-10deg); }
    68% { transform: rotate(7deg); }
    78% { transform: rotate(-3deg); }
    88%, 100% { transform: rotate(0); }
  }

  /* 8. Slash: 5s loop. In, swing, cut, spray, drip, pour, flood, fade. */
  .sl * { transform-box: view-box; }
  .sl-pool { animation: sl-in 5s cubic-bezier(.4,0,.3,1) infinite; }
  @keyframes sl-in {
    0% { transform: translate(-140px, -30px) rotate(-20deg); }
    10% { transform: translate(-20px, -40px) rotate(-6deg); }
    14% { transform: translate(0, 0); }
    16% { transform: translate(0, 3px) scaleY(.96); }
    18%, 32% { transform: translate(0, 0); }
    40% { transform: translate(90px, -50px) rotate(12deg); }
    48%, 100% { transform: translate(280px, -20px) rotate(20deg); }
  }
  .sl-arm { transform-origin: 60px 104px; animation: sl-swing 5s cubic-bezier(.7,0,.2,1) infinite; }
  @keyframes sl-swing {
    0%, 15% { transform: rotate(-40deg); }
    18% { transform: rotate(-80deg); }
    22%, 100% { transform: rotate(120deg); }
  }
  .sl-cut { fill: none; stroke: #fff; stroke-width: 4; stroke-linecap: round; stroke-dasharray: 245; stroke-dashoffset: 245; animation: sl-cut 5s ease-out infinite; }
  @keyframes sl-cut {
    0%, 19% { stroke-dashoffset: 245; stroke: #fff; stroke-width: 4; }
    22% { stroke-dashoffset: 0; stroke: #fff; stroke-width: 6; }
    28%, 100% { stroke-dashoffset: 0; stroke: #8a0007; stroke-width: 3; }
  }
  .sl-top { animation: sl-top 5s ease-out infinite; }
  .sl-bot { animation: sl-bot 5s ease-out infinite; }
  @keyframes sl-top { 0%, 22% { transform: none; } 26%, 92% { transform: translate(-2px, -3px); } 100% { transform: none; } }
  @keyframes sl-bot { 0%, 22% { transform: none; } 26%, 92% { transform: translate(2px, 3px); } 100% { transform: none; } }
  .sl-flash { fill: #fff; opacity: 0; animation: sl-flash 5s linear infinite; }
  @keyframes sl-flash { 0%, 21% { opacity: 0; } 22% { opacity: .85; } 27%, 100% { opacity: 0; } }
  .sl-spray { fill: #c8000a; opacity: 0; animation: sl-spray 5s cubic-bezier(.2,.7,.4,1) infinite; }
  @keyframes sl-spray {
    0%, 22% { opacity: 0; transform: translate(0, 0) scale(.4); }
    23% { opacity: 1; }
    30% { opacity: 1; transform: translate(var(--dx), var(--dy)) scale(1); }
    40%, 100% { opacity: 0; transform: translate(calc(var(--dx) * 1.3), calc(var(--dy) * -0.4)) scale(.8); }
  }
  .sl-drip { transform: scaleY(0); animation: sl-drip 5s cubic-bezier(.5,0,.8,.6) infinite; }
  @keyframes sl-drip { 0%, 25% { transform: scaleY(0); } 34% { transform: scaleY(.35); } 40% { transform: scaleY(.3); } 62% { transform: scaleY(1); } 94% { transform: scaleY(1.15); opacity: 1; } 100% { transform: scaleY(1.15); opacity: 0; } }
  .sl-fall { opacity: 0; animation: sl-fall 5s ease-in infinite; }
  @keyframes sl-fall { 0%, 60% { opacity: 0; transform: translateY(0); } 62% { opacity: 1; transform: translateY(0); } 74% { opacity: 1; transform: translateY(120px); } 75%, 100% { opacity: 0; transform: translateY(120px); } }
  .sl-sheet { animation: sl-sheet 5s cubic-bezier(.45,0,.6,1) infinite; }
  @keyframes sl-sheet { 0%, 30% { transform: translateY(8px); opacity: 1; } 60% { transform: translateY(130px); opacity: 1; } 84%, 94% { transform: translateY(232px); opacity: 1; } 100% { transform: translateY(232px); opacity: 0; } }
  .sl-sheet2 { animation: sl-sheet2 5s cubic-bezier(.45,0,.6,1) infinite; }
  @keyframes sl-sheet2 { 0%, 50% { transform: translateY(-44px); opacity: 1; } 86%, 94% { transform: translateY(232px); opacity: 1; } 100% { transform: translateY(232px); opacity: 0; } }
  .sl-shake { animation: sl-shake 5s linear infinite; }
  @keyframes sl-shake { 0%, 21% { transform: none; } 22% { transform: translate(4px, -3px); } 24% { transform: translate(-4px, 3px); } 26% { transform: translate(2px, 1px); } 28%, 100% { transform: none; } }
  .sl-oops { font: italic 800 14px/1 system-ui, sans-serif; fill: var(--ink); opacity: 0; animation: sl-oops 5s ease-out infinite; }
  @keyframes sl-oops { 0%, 30% { opacity: 0; transform: translateY(6px); } 34%, 44% { opacity: 1; transform: none; } 50%, 100% { opacity: 0; } }

  /* 10. Chimichanga break: mask rolled up, chewing. */
  .chomp { transform-box: view-box; transform-origin: 60px 106px; animation: chomp .3s ease-in-out infinite alternate; }
  @keyframes chomp { from { transform: scaleY(.25); } to { transform: scaleY(1); } }
  .chimi { transform-box: view-box; animation: chimi 1.4s cubic-bezier(.5,0,.3,1) infinite; }
  @keyframes chimi { 0%, 100% { transform: translate(34px, 6px) rotate(14deg); } 45%, 55% { transform: translate(0, 0) rotate(0); } }
  .crumb { fill: #e0a33a; transform-box: view-box; animation: crumb 1.4s ease-out infinite; opacity: 0; }
  @keyframes crumb { 0%, 48% { opacity: 0; transform: none; } 52% { opacity: 1; } 100% { opacity: 0; transform: translate(var(--dx), 26px); } }
  .nom { font: 900 13px/1 system-ui, sans-serif; fill: #fff; stroke: var(--ink); stroke-width: 3; paint-order: stroke; transform-box: view-box; animation: nom 1.4s ease-out infinite; opacity: 0; }
  @keyframes nom { 0%, 48% { opacity: 0; transform: translateY(4px); } 56%, 80% { opacity: 1; transform: none; } 100% { opacity: 0; transform: translateY(-6px); } }

  /* 11. Fourth wall: he peeks in, waves, winks, says it, leaves. 4s loop. */
  .peek { transform-box: view-box; animation: peek 4s cubic-bezier(.4,1.4,.5,1) infinite; }
  @keyframes peek { 0%, 4% { transform: translateX(110px) rotate(20deg); } 16%, 78% { transform: translateX(0) rotate(-14deg); } 92%, 100% { transform: translateX(110px) rotate(20deg); } }
  .wave { transform-box: view-box; transform-origin: 100px 128px; animation: wave .35s ease-in-out infinite alternate; }
  @keyframes wave { from { transform: rotate(-22deg); } to { transform: rotate(18deg); } }
  .wink { transform-box: view-box; transform-origin: 85px 60px; animation: wink 4s infinite; }
  @keyframes wink { 0%, 40% { transform: scaleY(1); } 43%, 52% { transform: scaleY(.08); } 55%, 100% { transform: scaleY(1); } }
  .bubble { transform-box: view-box; transform-origin: 40px 52px; animation: bubble 4s ease-out infinite; opacity: 0; }
  @keyframes bubble { 0%, 26% { opacity: 0; transform: scale(.4); } 32%, 74% { opacity: 1; transform: scale(1); } 80%, 100% { opacity: 0; transform: scale(.9); } }

  /* 12. Finger guns: pew pew, alternating, with a smug nod. */
  .gun-l, .gun-r { transform-box: view-box; animation: recoil .9s ease-out infinite; }
  .gun-l { transform-origin: 30px 118px; }
  .gun-r { transform-origin: 140px 118px; animation-delay: .45s; }
  @keyframes recoil { 0%, 8% { transform: rotate(0); } 14% { transform: rotate(-24deg); } 40%, 100% { transform: rotate(0); } }
  .gun-r { animation-name: recoil-r; }
  @keyframes recoil-r { 0%, 8% { transform: rotate(0); } 14% { transform: rotate(24deg); } 40%, 100% { transform: rotate(0); } }
  .pew { font: 900 12px/1 system-ui, sans-serif; fill: #ffd23f; stroke: var(--ink); stroke-width: 3; paint-order: stroke; transform-box: view-box; animation: pew .9s ease-out infinite; opacity: 0; }
  .pew.r { animation-delay: .45s; }
  @keyframes pew { 0%, 10% { opacity: 0; transform: scale(.5); } 16% { opacity: 1; transform: scale(1.15) translateY(-4px); } 50%, 100% { opacity: 0; transform: translateY(-14px); } }
  .nod { transform-box: view-box; transform-origin: 85px 120px; animation: nod .45s ease-in-out infinite alternate; }
  @keyframes nod { from { transform: rotate(-4deg) translateY(0); } to { transform: rotate(4deg) translateY(2px); } }

  svg.scene { width: 220px; height: 220px; filter: none; border-radius: 14px; overflow: hidden; }
  .sc * { transform-box: view-box; }
  .gl { fill: #2b2f38; stroke: var(--ink); stroke-width: 3; }
  .red { fill: #b3121b; }
  /* 13. Saw blade */
  .mb-saw { animation: mb-saw 3.5s linear infinite; }
  @keyframes mb-saw { 0% { transform: translate(-40px, -28px); } 70%, 100% { transform: translate(240px, 165px); } }
  .mb-spin { transform-origin: 0 0; animation: spin .25s linear infinite; }
  .mb-trail { fill: none; stroke: #b3121b; stroke-width: 5; stroke-linecap: round; stroke-dasharray: 250; animation: mb-trail 3.5s linear infinite; }
  @keyframes mb-trail { 0% { stroke-dashoffset: 250; } 60%, 100% { stroke-dashoffset: 0; } }
  .mb-guy { animation: mb-guy 3.5s step-end infinite; }
  @keyframes mb-guy { 0% { opacity: 1; } 34%, 100% { opacity: 0; } }
  .mb-splat { transform: scale(0); animation: mb-splat 3.5s cubic-bezier(.2,1.6,.4,1) infinite; }
  @keyframes mb-splat { 0%, 33% { transform: scale(0); } 40% { transform: scale(1); } 100% { transform: scale(1) translateY(14px); } }
  .mb-chunk { opacity: 0; animation: mb-chunk 3.5s ease-out infinite; }
  @keyframes mb-chunk { 0%, 33% { opacity: 0; transform: none; } 34% { opacity: 1; } 55% { opacity: 1; transform: translate(var(--dx), var(--dy)); } 100% { opacity: 1; transform: translate(var(--dx), calc(var(--dy) + 30px)); } }
  /* 14. Dash and ghosts */
  .mb-dash { animation: mb-dash 3.5s cubic-bezier(.7,0,.3,1) infinite; }
  @keyframes mb-dash { 0%, 10% { transform: translateX(-60px); } 30%, 100% { transform: translateX(150px); } }
  .mb-smear { transform-origin: 0 120px; transform: scaleX(0); animation: mb-smear 3.5s cubic-bezier(.7,0,.3,1) infinite; }
  @keyframes mb-smear { 0%, 10% { transform: scaleX(0); } 30%, 100% { transform: scaleX(1); } }
  .mb-ghost { opacity: 0; animation: mb-ghost 3.5s ease-out infinite; }
  @keyframes mb-ghost { 0%, 38% { opacity: 0; transform: none; } 44%, 58% { opacity: .45; transform: none; } 60% { opacity: 0; transform: translate(var(--gx), var(--gy)); } 100% { opacity: 0; } }
  .mb-pop { transform: scale(0); animation: mb-pop 3.5s cubic-bezier(.2,1.6,.4,1) infinite; }
  @keyframes mb-pop { 0%, 59% { transform: scale(0); } 66% { transform: scale(1); } 100% { transform: scale(1); } }
  /* 15. Impact frame */
  .mb-norm { animation: mb-norm 4s step-end infinite; }
  @keyframes mb-norm { 0% { opacity: 1; } 20% { opacity: 0; } 30%, 100% { opacity: 1; } }
  .mb-imp { opacity: 0; animation: mb-imp 4s step-end infinite; }
  @keyframes mb-imp { 0% { opacity: 0; } 20% { opacity: 1; } 30%, 100% { opacity: 0; } }
  .mb-crack { fill: none; stroke: var(--ink); stroke-width: 3; stroke-dasharray: 300; stroke-dashoffset: 300; animation: mb-crack 4s ease-out infinite; }
  @keyframes mb-crack { 0%, 29% { stroke-dashoffset: 300; } 34%, 100% { stroke-dashoffset: 0; } }
  .mb-burst { transform: scale(0); animation: mb-burst 4s cubic-bezier(.2,1.8,.4,1) infinite; }
  @keyframes mb-burst { 0%, 30% { transform: scale(0); } 38% { transform: scale(1.1); } 44%, 100% { transform: scale(1); } }
  .mb-shake { animation: mb-shake 4s linear infinite; }
  @keyframes mb-shake { 0%, 30% { transform: none; } 31% { transform: translate(6px, -4px); } 33% { transform: translate(-6px, 4px); } 35% { transform: translate(3px, 2px); } 37%, 100% { transform: none; } }
  .mb-retry { font: 900 30px/1 system-ui, sans-serif; fill: #fff; stroke: var(--ink); stroke-width: 5; paint-order: stroke; transform-origin: 100px 100px; opacity: 0; animation: mb-retry 4s cubic-bezier(.2,1.6,.4,1) infinite; }
  @keyframes mb-retry { 0%, 55% { opacity: 0; transform: scale(3); } 62%, 100% { opacity: 1; transform: scale(1); } }
  .mb-dripx { transform: scaleY(0); animation: mb-dripx 4s ease-in infinite; }
  @keyframes mb-dripx { 0%, 40% { transform: scaleY(0); } 90%, 100% { transform: scaleY(1); } }

  /* 16. Baby hand */
  .dm-pop { animation: dm-pop 3.5s ease-in infinite; }
  @keyframes dm-pop { 0%, 18% { transform: none; opacity: 1; } 22% { transform: translate(10px, -30px) rotate(90deg); } 48% { transform: translate(40px, 120px) rotate(400deg); opacity: 1; } 49%, 100% { opacity: 0; } }
  .dm-baby { transform-origin: 140px 92px; transform: scale(0); animation: dm-baby 3.5s cubic-bezier(.2,1.6,.4,1) infinite; }
  @keyframes dm-baby { 0%, 45% { transform: scale(0); } 58%, 100% { transform: scale(1); } }
  .dm-wave { transform-origin: 140px 100px; animation: wave .3s ease-in-out infinite alternate; }
  .dm-pfft { font: 800 11px/1 system-ui, sans-serif; fill: var(--ink); opacity: 0; animation: dm-txt 3.5s infinite; }
  @keyframes dm-txt { 0%, 60% { opacity: 0; } 66%, 95% { opacity: 1; } 100% { opacity: 0; } }
  /* 17. Unicorn */
  .dm-ride { animation: dm-ride 4.5s linear infinite; }
  @keyframes dm-ride { from { transform: translateX(-130px); } to { transform: translateX(390px); } }
  .dm-gallop { animation: dm-gallop .3s ease-in-out infinite alternate; }
  @keyframes dm-gallop { from { transform: translateY(0) rotate(-3deg); } to { transform: translateY(-8px) rotate(3deg); } }
  .dm-horn { transform-origin: 104px 70px; animation: dm-horn .6s ease-in-out infinite alternate; }
  @keyframes dm-horn { from { transform: scaleX(.3); } to { transform: scaleX(1); } }
  .dm-rainbow { animation: dm-ride 4s linear infinite; }
  /* 18. Score card */
  .dm-card { transform-origin: 100px 60px; animation: dm-card 3s cubic-bezier(.2,1.5,.4,1) infinite; }
  @keyframes dm-card { 0%, 10% { transform: translateY(80px) rotate(-20deg); opacity: 0; } 25%, 90% { transform: none; opacity: 1; } 100% { transform: translateY(80px); opacity: 0; } }
  .dm-judge { transform-origin: 60px 120px; animation: dm-judge 1.5s ease-in-out infinite alternate; }
  @keyframes dm-judge { from { transform: rotate(-6deg); } to { transform: rotate(6deg); } }

  /* 19-21. 8-bit */
  .px { shape-rendering: crispEdges; }
  .px-font { font: 900 16px/1 "Courier New", monospace; fill: #fff; letter-spacing: 1px; }
  .px-hop { animation: px-hop 3.5s linear infinite; }
  @keyframes px-hop { 0%, 20% { transform: none; } 32% { transform: translateY(-50px); } 60% { transform: translateY(130px); } 100% { transform: translateY(130px); } }
  .px-over { opacity: 0; animation: px-over 3.5s step-end infinite; }
  @keyframes px-over { 0% { opacity: 0; } 64%, 96% { opacity: 1; } 100% { opacity: 0; } }
  .px-coin { transform-origin: 40px 60px; animation: px-coin .6s linear infinite; }
  @keyframes px-coin { 0%, 100% { transform: scaleX(1); } 50% { transform: scaleX(.15); } }
  .px-walk { animation: px-walk 4s steps(12) infinite; }
  @keyframes px-walk { 0% { transform: translateX(0); } 60%, 100% { transform: translateX(120px); } }
  .px-sink { animation: px-sink 4s steps(8) infinite; }
  @keyframes px-sink { 0%, 42% { transform: translateY(0); } 70%, 100% { transform: translateY(48px); } }
  .px-life { opacity: 0; animation: px-life 4s ease-out infinite; }
  @keyframes px-life { 0%, 70% { opacity: 0; transform: none; } 75% { opacity: 1; } 100% { opacity: 0; transform: translateY(-30px); } }
  .px-t3, .px-t2, .px-t1, .px-t0 { opacity: 0; animation: 4s step-end infinite; }
  .px-t3 { animation-name: px-t3; } .px-t2 { animation-name: px-t2; } .px-t1 { animation-name: px-t1; } .px-t0 { animation-name: px-t0; }
  @keyframes px-t3 { 0% { opacity: 1; } 20%, 100% { opacity: 0; } }
  @keyframes px-t2 { 0% { opacity: 0; } 20% { opacity: 1; } 40%, 100% { opacity: 0; } }
  @keyframes px-t1 { 0% { opacity: 0; } 40% { opacity: 1; } 60%, 100% { opacity: 0; } }
  @keyframes px-t0 { 0% { opacity: 0; } 60%, 100% { opacity: 1; } }
  .px-shrink { transform-origin: 100px 150px; animation: px-shrink 4s steps(4) infinite; }
  @keyframes px-shrink { 0%, 62% { transform: scale(1); } 80%, 100% { transform: scale(.45); } }
  .px-up { opacity: 0; animation: px-up 4s step-end infinite; }
  @keyframes px-up { 0% { opacity: 0; } 64% { opacity: 1; } 72% { opacity: 0; } 78%, 100% { opacity: 1; } }

  /* 22. YOU DIED */
  .mm-slump { transform-origin: 100px 160px; animation: mm-slump 4s ease-in infinite; }
